<h3 class="has-text-align-center has-text-color" style="color:#063733;font-size:22px;line-height:1.6;margin-top:0px;margin-bottom:16px">つばき整骨院さん　—　棚のファイルがぐっと減った</h3>
<!-- /wp:heading -->
<!-- wp:wdl/paid-block-before-after-1 {"beforeImageUrl":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/saas_before_2.webp","beforeImageAlt":"ファイルと書類箱がぎっしり詰まった棚","beforeText":"入れる前","afterImageUrl":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/saas_after_2.webp","afterImageAlt":"ファイルがわずかになった棚","afterText":"入れたあと","beforeTextBgColor":"#4a5a58","afterTextBgColor":"#0e5c55","arrowBgColor":"#8a5a00","maxWidth":860,"aspectRatioHeight":700,"hasImageShadow":true} -->
